def validate_dimensions(dimension: Union[int, float], attribute_name: str) -> int:

    dimension = int(dimension)
    if dimension <= 0 or dimension % 64 != 0:
        raise ValueError(f"The '{attribute_name}' must be a multiple of 64.")
    return dimension

